'use strict';
let mapDrag=null,mapGesture=null,edgeFrame=null;const mapPointers=new Map(),viewport=$('#mapViewport');
function mapXY(e){const b=viewport.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top}}
function hitCity(p){return state.members.filter(m=>m.slot).map(m=>({m,s:slotBy(m.slot)})).find(({s})=>s&&visible(s)&&p.x>=s.x&&p.x<s.x+2&&p.y>=s.y&&p.y<s.y+2)}
function applyCityMove(id,x,y){try{const m=state.members.find(m=>m.id===id),old=slotBy(m?.slot);if(old?.x===x&&old?.y===y){setTool('select');return}const next=Hive.moveCity(state,id,x,y);commit(()=>state=next);setTool('select');selectedMember=id;renderMap();toast('City moved. Undo is available.')}catch(e){toast(e.message)}}
const plainRenderMap=renderMap;renderMap=function(){plainRenderMap();if(!mapDrag?.started)return;const m=state.members.find(m=>m.id===mapDrag.id),s=slotBy(m.slot),box={...s,x:mapDrag.x,y:mapDrag.y};const valid=Hive.validCityPosition(state,box,m.id),poly=document.createElementNS('http://www.w3.org/2000/svg','polygon');poly.setAttribute('points',polygon(box));poly.setAttribute('fill',valid?'#7cac78':'#d08a7a');poly.setAttribute('fill-opacity','.7');poly.setAttribute('stroke',valid?'#244f31':'#9b3027');poly.setAttribute('stroke-width','3');poly.setAttribute('stroke-dasharray','5 3');poly.setAttribute('pointer-events','none');poly.setAttribute('data-drag-preview',valid?'valid':'invalid');$('#mapSvg').appendChild(poly);$('#mapHint').textContent=valid?'Release to place city · Esc to cancel':'Blocked position · release to cancel'};
function updateDrag(){if(!mapDrag)return;const p=screenWorld(mapDrag.screen.x,mapDrag.screen.y);mapDrag.x=Math.round(p.x-mapDrag.offset.x);mapDrag.y=Math.round(p.y-mapDrag.offset.y);renderMap()}
function edgePan(){if(!mapDrag?.started){edgeFrame=null;return}const b=viewport.getBoundingClientRect(),p=mapDrag.screen,pad=32,speed=7;let dx=p.x<pad?speed:p.x>b.width-pad?-speed:0,dy=p.y<pad?speed:p.y>b.height-pad?-speed:0;if(dx||dy){camera.x+=dx;camera.y+=dy;updateDrag()}edgeFrame=requestAnimationFrame(edgePan)}
function clearDrag(){if(edgeFrame)cancelAnimationFrame(edgeFrame);edgeFrame=null;mapDrag=null;renderMap();$('#mapHint').textContent='Drag a city to move it. Drag empty space to pan.'}
viewport.addEventListener('pointerdown',e=>{if(e.target.closest('.map-controls'))return;viewport.setPointerCapture(e.pointerId);const screen=mapXY(e),world=screenWorld(screen.x,screen.y);mapPointers.set(e.pointerId,screen);if(mapPointers.size>1){clearDrag();const a=[...mapPointers.values()];mapGesture={moved:true,pinch:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)};return}mapGesture={start:screen,last:screen,moved:false,target:e.target};const hit=hitCity(world);if(!readonly&&tool==='select'&&hit){mapDrag={id:hit.m.id,locked:!!hit.m.locked,x:hit.s.x,y:hit.s.y,screen,offset:{x:world.x-hit.s.x,y:world.y-hit.s.y},started:false}}});
viewport.addEventListener('pointermove',e=>{if(!mapPointers.has(e.pointerId)||!mapGesture)return;const p=mapXY(e),old=mapPointers.get(e.pointerId);mapPointers.set(e.pointerId,p);if(mapPointers.size>1){const a=[...mapPointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);if(mapGesture.pinch)zoom(d/mapGesture.pinch,(a[0].x+a[1].x)/2,(a[0].y+a[1].y)/2);mapGesture.pinch=d;mapGesture.moved=true;return}if(!mapGesture.start)return;const distance=Math.hypot(p.x-mapGesture.start.x,p.y-mapGesture.start.y);if(distance>6)mapGesture.moved=true;if(!mapGesture.moved)return;if(mapDrag){if(mapDrag.locked){$('#mapHint').textContent='City locked. Unlock it before moving.';return}mapDrag.started=true;mapDrag.screen=p;updateDrag();if(!edgeFrame)edgeFrame=requestAnimationFrame(edgePan)}else{camera.x+=p.x-old.x;camera.y+=p.y-old.y;renderMap()}});
viewport.addEventListener('pointerup',e=>{mapPointers.delete(e.pointerId);if(mapPointers.size)return;const g=mapGesture,d=mapDrag;mapGesture=null;clearDrag();if(d?.started){applyCityMove(d.id,d.x,d.y);return}if(g&&!g.moved)mapTap(e,g.target)});
viewport.addEventListener('pointercancel',e=>{mapPointers.delete(e.pointerId);mapGesture=null;clearDrag()});
viewport.addEventListener('lostpointercapture',()=>{if(!mapPointers.size)return;mapPointers.clear();mapGesture=null;clearDrag()});
viewport.addEventListener('wheel',e=>{e.preventDefault();const p=mapXY(e);zoom(e.deltaY<0?1.1:1/1.1,p.x,p.y)},{passive:false});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){mapPointers.clear();mapGesture=null;clearDrag()}});
function layoutPreview(reset){if(activeTrap==='all'){toast('Select BT 1 or BT 2 before changing its layout.');return}const trap=+activeTrap;let result;try{result=reset?Hive.resetLayout(state,trap):Hive.compactLayout(state,trap)}catch(e){toast(e.message);return}const coords=p=>p?`Row ${p.row} · X:${state.settings.anchorX+p.x} Y:${state.settings.anchorY+p.y}`:'Unassigned queue';openModal(`<div class="eyebrow">BT ${trap} · LAYOUT PREVIEW</div><h2>${reset?'Reset to the default layout?':'Compact this formation?'}</h2><p>${reset?'Restore valid default city spots. Roster, attendance, trap coordinates, terrain and fixed structures are preserved.':'Close avoidable gaps using a compact grid heuristic. This does not silently swap players by attendance.'} Locked cities remain fixed. The other trap is preserved.</p><div class="notice">${esc(result.notes)}${result.unassigned?`<br>${result.unassigned} players cannot fit and will be unassigned.`:''}</div><div class="preview-list">${result.changes.map(c=>`<div class="preview-item"><strong>${esc(c.name)}</strong><small>From ${esc(coords(c.from))}</small><small>To ${esc(coords(c.to))}</small></div>`).join('')||'<p>No player moves are needed. Empty city spots may be reset.</p>'}</div><div class="actions"><button class="primary" id="applyLayout">${reset?'Reset BT '+trap+' layout':'Apply compact layout'}</button><button id="cancelLayout">Keep current layout</button></div><p>The complete change can be undone with one Undo.</p>`);$('#applyLayout').onclick=()=>{commit(()=>state=result.state);closeModal();fit();toast(reset?'Layout reset. Undo is available.':'Layout compacted. Undo is available.')};$('#cancelLayout').onclick=closeModal}
$('#compactBtn').onclick=()=>layoutPreview(false);$('#resetLayoutBtn').onclick=()=>layoutPreview(true);
